// Sector / sub-sector taxonomy for the Intake form (/new). Two mandatory
// dropdowns instead of the free-text field the original spec called for —
// an explicit product decision (2026-09-03) to know exactly what kind of
// business each respondent runs, at the cost of maintaining this list.
// Stored value is a plain English string ("Sector — Sub-sector"), same
// storage shape as before (Intake.sector / Business.sector are unchanged,
// still `sector: string`) — only the input UI changed, not the schema.
//
// 40 top-level sectors, ~460 sub-sectors, translated into all 5 UI languages.
// Generated once from a fixed English taxonomy; ids are stable kebab/snake_case
// slugs derived from the English name, de-duplicated where two sub-sectors in
// different groups would otherwise collide is not needed since ids are scoped
// per-group by lookup, but each group's own id is globally unique.

import type { Language } from "./types";

export type Row = Record<Language, string>;
const row = (en: string, uz: string, ru: string, zh: string, fr: string): Row => ({ en, uz, ru, zh, fr });

export interface SubSector {
  id: string;
  name: Row;
}
export interface SectorGroup {
  id: string;
  name: Row;
  subsectors: SubSector[];
}

