export function findSectorGroup(groupId: string): SectorGroup | undefined {
  return SECTOR_TAXONOMY.find((g) => g.id === groupId);
}
export function findSubSector(groupId: string, subId: string): SubSector | undefined {
  return findSectorGroup(groupId)?.subsectors.find((s) => s.id === subId);
}
// English canonical combined label — this is what gets stored (Business.sector
// stays a plain, untranslated string, same as the original free-text field did).
export function sectorDisplayLabel(groupId: string, subId: string): string {
  const group = findSectorGroup(groupId);
  const sub = findSubSector(groupId, subId);
  if (!group || !sub) return "";
  return `${group.name.en} — ${sub.name.en}`;
}
